/**
 * Forward-only, versioned migrations. They are embedded as strings so the bundled server needs no
 * loose .sql files. Each runs in its own transaction during startup and offline updates.
 *
 * Data rules (see docs/ARCHITECTURE.md §5):
 *  - UUIDv7 primary keys generated by the app; human-readable numbers come from number_series.
 *  - Money = bigint paise. Financial rows are never updated or deleted; corrections are new rows.
 *  - Every table carries created/updated metadata and row_version, ready for future sync.
 */
import type { Db } from "./index.js";

const meta = `
  created_at  timestamptz not null default now(),
  created_by  text not null default 'system',
  updated_at  timestamptz not null default now(),
  updated_by  text not null default 'system',
  row_version integer not null default 1`;

export const migrations: { id: number; name: string; sql: string }[] = [
  {
    id: 1,
    name: "core_front_desk",
    sql: `
      create schema if not exists core;

      create table core.facility (
        id      integer primary key default 1 check (id = 1),
        name    text not null,
        address text not null default '',
        phone   text not null default '',
        uhid_prefix text not null default 'HS-',
        ${meta}
      );

      -- Gap-free, per-key counters: UHID, invoice numbers per financial year, tokens per doctor per day.
      create table core.number_series (
        key        text primary key,
        next_value bigint not null
      );

      create table core.patient (
        id            uuid primary key,
        uhid          text not null unique,
        name          text not null,
        name_search   text not null,
        sex           char(1) not null check (sex in ('M','F','O')),
        phone         text not null,
        dob           date,
        dob_estimated boolean not null default false,
        deleted_at    timestamptz,
        ${meta}
      );
      create index patient_phone_idx on core.patient (phone);
      create index patient_name_idx  on core.patient (name_search text_pattern_ops);

      create table core.practitioner (
        id               uuid primary key,
        name             text not null,
        department       text not null,
        consultation_fee bigint not null check (consultation_fee >= 0),
        slot_minutes     integer not null default 10 check (slot_minutes between 5 and 120),
        day_start        time not null default '09:00',
        day_end          time not null default '13:00',
        active           boolean not null default true,
        ${meta}
      );

      create table core.appointment (
        id              uuid primary key,
        patient_id      uuid not null references core.patient(id),
        practitioner_id uuid not null references core.practitioner(id),
        slot_start      timestamptz not null,
        visit_date      date not null,
        token           integer not null,
        status          text not null default 'BOOKED'
                        check (status in ('BOOKED','CHECKED_IN','IN_CONSULT','DONE','CANCELLED')),
        ${meta}
      );
      -- The database itself prevents double-booking, even with many reception desks at once.
      create unique index appointment_slot_uq on core.appointment (practitioner_id, slot_start) where status <> 'CANCELLED';
      create index appointment_date_idx on core.appointment (visit_date);

      create table core.invoice (
        id             uuid primary key,
        invoice_no     text not null unique,
        patient_id     uuid not null references core.patient(id),
        appointment_id uuid references core.appointment(id),
        issued_at      timestamptz not null default now(),
        subtotal       bigint not null,
        discount       bigint not null default 0,
        total          bigint not null,
        status         text not null default 'PAID' check (status in ('DRAFT','PAID','CANCELLED')),
        check (discount <= subtotal and total = subtotal - discount),
        ${meta}
      );

      create table core.invoice_line (
        id          uuid primary key,
        invoice_id  uuid not null references core.invoice(id),
        line_no     integer not null,
        description text not null,
        quantity    integer not null check (quantity > 0),
        unit_price  bigint not null,
        amount      bigint not null,
        unique (invoice_id, line_no)
      );

      create table core.payment (
        id          uuid primary key,
        invoice_id  uuid not null references core.invoice(id),
        mode        text not null check (mode in ('CASH','UPI','CARD')),
        amount      bigint not null check (amount >= 0),
        received_at timestamptz not null default now(),
        received_by text not null
      );

      -- Retried requests (network blip, double click) return the original result instead of re-running.
      create table core.idempotency (
        key        uuid primary key,
        response   jsonb not null,
        created_at timestamptz not null default now()
      );

      -- Append-only, hash-chained audit trail: altering or deleting a past row breaks the chain.
      create table core.audit_event (
        seq       bigserial primary key,
        at        timestamptz not null default now(),
        actor     text not null,
        terminal  text not null,
        action    text not null,
        entity    text not null,
        entity_id text not null,
        data      jsonb not null default '{}',
        prev_hash text not null,
        hash      text not null
      );

      -- Outbox for anything that needs internet later (SMS, WhatsApp, ABDM, cloud sync).
      create table core.outbox (
        id         uuid primary key,
        topic      text not null,
        payload    jsonb not null,
        created_at timestamptz not null default now(),
        sent_at    timestamptz,
        attempts   integer not null default 0
      );
      create index outbox_pending_idx on core.outbox (created_at) where sent_at is null;
    `,
  },
];

export async function migrate(db: Db): Promise<void> {
  await db.query(`create table if not exists public.schema_migrations (id integer primary key, name text not null, applied_at timestamptz not null default now())`);
  const { rows } = await db.query<{ id: number }>("select id from public.schema_migrations");
  const applied = new Set(rows.map((r) => r.id));
  for (const m of migrations) {
    if (applied.has(m.id)) continue;
    await db.tx(async (q) => {
      await q.exec(m.sql);
      await q.query("insert into public.schema_migrations (id, name) values ($1, $2)", [m.id, m.name]);
    });
  }
}
